<!DOCTYPE html>
<html lang="{{ app()->getLocale() }}">
<head>
<meta charset="UTF-8">
<title>Carte Étudiant — GUT Center Ambilobe</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script>
<style>
  :root{
    --blue-deep: #16209b;
    --blue-mid: #3a2fc4;
    --purple: #a63fd6;
    --purple-light:#c76bea;
    --gold: #f4b400;
    --red: #e6392b;
    --ink: #1c1c28;
    --slate: #6b7280;
    --paper: #f5f6fb;
    --card-w: 560px;
    --card-h: 340px;
  }

  *{ box-sizing:border-box; }

  body{
    margin:0;
    min-height:100vh;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    gap:28px;
    background:
      radial-gradient(circle at 15% 10%, #eef0ff 0%, transparent 45%),
      radial-gradient(circle at 85% 90%, #fdf0e8 0%, transparent 45%),
      var(--paper);
    font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
    color: var(--ink);
    padding: 32px 16px;
  }

  .cards-row{
    display:flex;
    flex-wrap: wrap;
    align-items:flex-start;
    justify-content:center;
    gap: 32px;
  }
  .card-label{
    text-align:center;
    font-size: 11px;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--slate);
    font-weight: 700;
    margin-bottom: 10px;
  }

  h1{
    font-size: 15px;
    letter-spacing: 3px;
    text-transform: uppercase;
    color: var(--slate);
    font-weight: 600;
    margin: 0;
    text-align:center;
  }

  .hint{
    font-size: 12.5px;
    color: var(--slate);
    text-align:center;
    margin-top:-14px;
  }
  .hint kbd{
    background:#fff;
    border:1px solid #ddd;
    border-radius:4px;
    padding:1px 6px;
    font-size:11px;
  }

  .stage{
    width: var(--card-w);
  }

  .face{
    position:relative;
    width:100%;
    height: var(--card-h);
    border-radius: 22px;
    background: #fff;
    box-shadow: 0 22px 45px -18px rgba(20,20,60,0.45), 0 4px 12px rgba(20,20,60,0.12);
    overflow:hidden;
    display:flex;
    flex-direction:column;
  }

  /* ===== HEADER (both faces) ===== */
  .header{
    display:flex;
    align-items:center;
    justify-content:space-between;
    padding: 10px 14px 6px;
    gap:8px;
  }
  .brand-title{
    flex:1;
    text-align:center;
    font-size: 15px;
    font-weight: 800;
    letter-spacing: 0.5px;
    color: var(--ink);
    white-space: nowrap;
  }
  .logo{
    width:38px;
    height:38px;
    border-radius:50%;
    flex-shrink:0;
    overflow:hidden;
    box-shadow: 0 2px 6px rgba(0,0,0,0.2);
  }
  .logo img{
    width:100%;
    height:100%;
    object-fit: cover;
    display:block;
  }

  /* ===== FRONT ===== */
  .front-body{
    display:flex;
    flex:1;
    gap: 12px;
    padding: 0 14px 12px;
    min-height:0;
  }

  .photo-panel{
    width: 145px;
    flex-shrink:0;
    border-radius: 12px;
    background: linear-gradient(160deg, var(--blue-deep) 0%, var(--blue-mid) 38%, var(--purple) 72%, var(--purple-light) 100%);
    display:flex;
    flex-direction:column;
    align-items:center;
    padding: 10px 8px;
    text-align:center;
    color:#fff;
  }
  .photo-frame{
    width: 100%;
    aspect-ratio: 1/1;
    border-radius: 8px;
    overflow:hidden;
    background: linear-gradient(180deg,#cfe8ff 0%, #e8f4ff 55%, #9bd06a 55%, #6fae3e 100%);
    position:relative;
    box-shadow: 0 3px 8px rgba(0,0,0,0.25);
  }
  .photo-frame .cloud{
    position:absolute; top:22%; left:22%;
    width:38%; height:26%;
    background:#fff;
    border-radius:50%;
    box-shadow: 18px 4px 0 -4px #fff, -14px 6px 0 -6px #fff;
    opacity:0.95;
  }
  .photo-initial{
    width:100%; height:100%;
    display:flex; align-items:center; justify-content:center;
    background:#3a2fc4; color:#fff;
    font-size:48px; font-weight:800;
    text-transform:uppercase;
  }
  .stud-name{
    margin-top: 6px;
    font-weight: 800;
    font-size: 13px;
    line-height:1.2;
    max-width:100%;
    white-space:normal;
    overflow-wrap:anywhere;
    word-break:break-word;
  }
  .stud-role{
    margin-top: 4px;
    font-size: 12px;
    font-weight: 300;
    opacity:0.9;
  }
  .stud-id{
    margin-top: 3px;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.5px;
  }
  .stud-level{
    margin-top: 4px;
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.5px;
  }

  .info-panel{ flex:1; min-width:0; display:flex; flex-direction:column; }
  .info-pill{
    display:inline-block;
    background: linear-gradient(90deg, var(--blue-mid), #2fae8a);
    color:#fff;
    font-size: 10.5px;
    font-weight: 700;
    padding: 5px 12px;
    border-radius: 14px;
    align-self:flex-start;
    margin-bottom: 8px;
  }
  .field{ margin-bottom: 5px; width:100%; }
  .field .label{
    font-size: 10px;
    color: var(--slate);
    font-weight: 500;
  }
  .field .value{
    font-size: 12px;
    font-weight: 700;
    color: var(--ink);
    margin-top: 0px;
    word-break: break-word;
  }

  .signature-block{
    margin-top: auto;
    padding-top: 6px;
    text-align:right;
    font-size: 10px;
    color: var(--ink);
    line-height:1.4;
    width:100%;
  }
  .signature-block .role{ color: var(--slate); font-size:9.5px; }
  .signature-block .name{ font-weight: 800; }

  /* ===== BACK ===== */
  .back-body{
    flex:1;
    display:flex;
    flex-direction:row;
    align-items:center;
    justify-content:center;
    gap: 24px;
    padding: 8px 24px;
    min-height:0;
  }
  #qrcode{
    flex-shrink:0;
    padding: 8px;
    background:#fff;
    border-radius: 10px;
  }
  #qrcode img{ display:block; width:100px; height:100px; }

  .contact{
    flex:0 1 auto;
    min-width:0;
    font-size: 12px;
    text-align:center;
  }
  .contact .label{
    color: var(--slate);
    font-size: 10.5px;
    margin-bottom: 3px;
  }
  .contact .lines{ font-weight: 700; line-height: 1.5; margin-bottom: 10px; }

  .email-tag{
    align-self:center;
    margin: 0 0 8px;
    background: var(--red);
    color:#fff;
    font-weight:800;
    font-size: 11px;
    text-align:center;
    padding: 8px 14px;
    border-radius: 8px;
    box-shadow: 0 6px 14px rgba(230,57,43,0.35);
  }

  .footer-band{
    background: linear-gradient(90deg, var(--blue-deep), var(--purple));
    color:#fff;
    text-align:center;
    font-weight: 800;
    letter-spacing: 1px;
    font-size: 13px;
    padding: 12px 12px;
  }

  @media (max-width: 860px){
    :root{ --card-w: 88vw; --card-h: 340px; }
    .cards-row{ flex-direction: column; align-items:center; }
  }

  /* PDF layout: keep the supplied card design intact, one face per page. */
  @media print {
    html, body { width:420pt; min-height:255pt; }
    body { display:block; padding:0; background:#fff; }
    h1, .card-label { display:none; }
    .cards-row { display:block; width:420pt; }
    .stage { width:420pt; page-break-after:always; }
    .stage:last-child { page-break-after:auto; }
    .face { width:420pt; height:220pt; }
  }

  /* Dompdf renders this view as the downloadable card, so remove the web-only
     wrapper and preserve the model's proportions on a two-page PDF. */
  @page { size:420pt 220pt; margin:0; }
  html, body { width:420pt; min-height:220pt; }
  body { display:block; padding:0; background:#fff; }
  h1, .card-label { display:none; }
  .cards-row { display:block; width:420pt; }
  .stage { width:420pt; page-break-after:always; }
  .stage:last-child { page-break-after:auto; }
  .face { width:420pt; height:220pt; display:block; position:relative; overflow:hidden; page-break-inside:avoid; }
  .header { position:absolute; top:0; left:0; right:0; height:55px; }
  .header .logo { position:absolute; top:10px; }
  .header .logo:first-child { left:14px; }
  .header .logo:last-child { right:14px; }
  .header .brand-title { position:absolute; top:14px; left:70px; right:70px; }
  .front-body { position:absolute; top:52px; left:0; right:0; height:235px; bottom:auto; }
  .front-body { display:block; }
  .front-body .photo-panel { position:absolute; left:14px; top:0; width:145px; height:235px; }
  .front-body .photo-panel { background:#3a2fc4; }
  .front-body .photo-frame { width:129px; height:129px; aspect-ratio:auto; flex-shrink:0; }
  .front-body .info-panel { position:absolute; left:190px; top:0; right:14px; height:235px; }
  .info-panel .signature-block { position:absolute; right:0; bottom:0; }
  .back-body { position:absolute; top:50px; left:0; right:0; height:185px; bottom:auto; }
  .back-body { display:block; }
  .back-body #qrcode { position:absolute; left:210px; top:8px; }
  .back-body .contact { position:absolute; left:190px; top:132px; width:180px; font-size:10px; }
  .back-body .contact .label { font-size:9px; }
  .back-body .contact .lines { line-height:1.3; }
  .info-pill { background:#3a2fc4; }
  .email-tag { position:absolute; left:0; right:0; bottom:43px; margin:0 auto; width:max-content; }
  .footer-band { position:absolute; left:0; right:0; bottom:0; background:#16209b; }
</style>
</head>
<body>

  <div class="cards-row">

    <div class="stage">
      <!-- ============ RECTO ============ -->
      <div class="face front">
        <div class="header">
          <div class="logo">
            <img src="data:image/png;base64," alt="GUT Center logo">
          </div>
          <div class="brand-title">GUT CENTER AMBILOBE</div>
          <div class="logo">
            <img src="data:image/png;base64," alt="GUT Center logo">
          </div>
        </div>

        <div class="front-body">
          <div class="photo-panel">
            <div class="photo-frame">
              @if($photo)
                <img src="{{ $photo }}" alt="{{ __('Profile photo') }}" style="width:100%;height:100%;object-fit:cover;display:block;">
              @else
                <div class="photo-initial">{{ mb_strtoupper(mb_substr(trim($cardName ?: '?'), 0, 1)) }}</div>
              @endif
            </div>
            <div class="stud-name" id="f-name">{{ mb_strtoupper(trim($cardName)) }}</div>
            <div class="stud-role">{{ $cardRole }}</div>
            <div class="stud-id" id="f-id">{{ $cardId }}</div>
            <div class="stud-level" id="f-level">{{ $cardClass ?: '—' }}</div>
          </div>

          <div class="info-panel">
            <div class="info-pill">Informations Personnelles</div>

            <div class="field">
              <div class="label">Date de naissance :</div>
              <div class="value" id="f-dob">{{ $cardBirthDate ?: '—' }}</div>
            </div>
            <div class="field">
              <div class="label">Address :</div>
              <div class="value" id="f-address">{{ $cardAddress ?: '—' }}</div>
            </div>
            <div class="field">
              <div class="label">Fonction :</div>
              <div class="value" id="f-role">{{ $cardFunction }}</div>
            </div>
            <div class="field">
              <div class="label">{{ $cardIsProfessional ? 'Téléphone :' : 'Téléphone tuteur :' }}</div>
              <div class="value" id="f-phone">{{ $cardPhone ?: '—' }}</div>
            </div>

            <div class="signature-block">
              <div class="role">Directeur Général</div>
              <div class="name">Gautier BETIANA</div>
            </div>
          </div>
        </div>
      </div>
    </div>

    <div class="stage">
      <!-- ============ VERSO ============ -->
      <div class="face back">
        <div class="header">
          <div class="logo">
            <img src="data:image/png;base64," alt="GUT Center logo">
          </div>
          <div class="brand-title">GUT CENTER AMBILOBE</div>
          <div class="logo">
            <img src="data:image/png;base64," alt="GUT Center logo">
          </div>
        </div>

        <div class="back-body">
          <div id="qrcode"><img src="data:image/svg+xml;base64,{{ $qr }}" alt="QR code" style="width:100px;height:100px;display:block;"></div>

          <div class="contact">
            <div class="label">Siège :</div>
            <div class="lines">
              AMBILOBE<br>
              Lot III, 6 Antanamariazy<br>
              Tel : +261 32 77 366 80
            </div>
          </div>
        </div>

        <div class="email-tag">Email: gutcenter204@gmail.com</div>
        <div class="footer-band">GO UP TOGETHER — LANGUAGES TRAINING</div>
      </div>
    </div>

  </div>

<script>
  // Generate a QR code (points to student ID record — change the text/URL as needed)
  const qrData = "ST26-0001 | JAOMAMY MARTIAL | GUT Center Ambilobe";

  new QRCode(document.getElementById("qrcode"), {
    text: qrData,
    width: 100,
    height: 100,
    colorDark: "#16209b",
    colorLight: "#ffffff",
    correctLevel: QRCode.CorrectLevel.H
  });
</script>

</body>
</html>
